      "svc-sea.hero.subtitle": "Global Kapsam — dünyanın tüm limanlarından bulk ve konteyner yüklerin güvenli denizyolu taşımacılığı.",
      "svc-sea.desc.media.alt": "Konteyner gemisi denizyolu taşıması",
