      "svc-sea.desc.heading": "Limandan Limana Güvenli Deniz Taşımacılığı",
      "svc-sea.desc.p1": "Dünyanın tüm limanlarından Bulk ve Konteyner yüklerin ilgili limanlar arasında taşıma hizmetini gerçekleştirmekteyiz. Volga Nehri üzerinden yine Bulk yükler için gemi taşıma hizmeti vermekteyiz.",
      "svc-sea.desc.p2": "Caspian Sea (Hazar Denizi) içerisinde komşu ülkeler arası / komşu ülkeler üzerinden transit yükler için gemi taşıma hizmeti vererek, Orta Asya ile Kafkasya arasındaki deniz bağlantısını güvenle sağlıyoruz.",
      "svc-sea.desc.cta": "Bu Hizmet İçin Teklif Al",
