      "svc-rail.meta.title": "Demiryolu Taşımacılığı | CEN Logistics Group",
      "svc-rail.meta.description": "BTK hattı ve Middle Corridor üzerinden Türkiye, Kafkasya, Orta Asya, Rusya, İran, Avrupa ve Çin arasında demiryolu konteyner ve vagon taşımacılığı.",
      "svc-rail.hero.title": "Demiryolu Taşımacılığı",
      "svc-rail.hero.subtitle": "BTK Hattı ve Middle Corridor üzerinden Türkiye, Kafkasya, Orta Asya, Rusya, İran, Avrupa ve Çin arasında güvenilir demiryolu konteyner ve vagon taşımacılığı.",
      "svc-rail.desc.media.alt": "Demiryolu konteyner taşıması",
      "svc-rail.desc.eyebrow": "Açıklama",
      "svc-rail.desc.heading": "Bölgesel Uzmanlıkla Kesintisiz Demiryolu Ağı",
      "svc-rail.desc.p1": "Demiryolu konusunda hizmetlerimizi kendi bölgelerinde uzman, deneyimli ve güvenilir marka olan ana operatörlerimiz ve bünyemizdeki deneyimli uzmanlarımız ile sağlıyoruz.",
      "svc-rail.desc.p2": "\u003cstrong\u003eBTK Hattı\u003c/strong\u003e ile Türkiye, Gürcistan, Azerbaycan, Türkmenistan, Özbekistan ve Kazakistan arasında 20 ft, 40 ft ve 45 ft konteyner taşıması; Kazakistan, Özbekistan, Türkmenistan ve Rusya arasında konteyner ve vagon taşımaları gerçekleştiriyoruz. Çin\u0027den \u003cstrong\u003eMiddle Corridor\u003c/strong\u003e üzerinden Türkiye ve Avrupa\u0027ya düzenli demiryolu konteyner taşımaları sunuyor; Avrupa/Türkiye demiryolu konteyner \u0026amp; vagon taşımalarını ve Türkmenistan–İran–Türkiye koridorunda konteyner ve vagon taşımalarını yönetiyoruz.",
      "svc-rail.desc.cta": "Bu Hizmet İçin Teklif Al",
      "svc-rail.advantages.eyebrow": "Neden Bizimle",
      "svc-rail.advantages.heading": "Avantajlar",
      "svc-rail.advantages.card1.title": "BTK Hattı Uzmanlığı",
      "svc-rail.advantages.card1.desc": "Bakü–Tiflis–Kars hattında 20/40/45 ft konteyner taşımalarında bölgesel operatör deneyimi.",
      "svc-rail.advantages.card2.title": "Middle Corridor Düzenli Sefer",
      "svc-rail.advantages.card2.desc": "Çin\u0027den Türkiye ve Avrupa\u0027ya, Orta Koridor üzerinden düzenli demiryolu konteyner taşımaları.",
      "svc-rail.advantages.card3.title": "Geniş Koridor Ağı",
      "svc-rail.advantages.card3.desc": "Kazakistan, Özbekistan, Türkmenistan, Rusya, İran ve Avrupa arasında konteyner \u0026amp; vagon taşıma imkânı.",
