      "svc-road.meta.description": "TIR ve dorse filomuzla iki nokta arasında, sınır ötesi ve door-to-door karayolu taşımacılığı hizmetleri.",
      "svc-road.hero.title": "Karayolu Taşımacılığı",
      "svc-road.hero.subtitle": "TIR ve dorse filomuzla iki nokta arasında, sınır ötesi ve door-to-door karayolu taşımacılığında esnek ve güvenilir çözümler.",
      "svc-road.desc.media.alt": "Karayolu TIR taşımacılığı",
      "svc-road.desc.eyebrow": "Açıklama",
      "svc-road.desc.heading": "İki Nokta Arasında Esnek Karayolu Çözümleri",
      "svc-road.desc.p1": "CEN Logistics Group çatısı altındaki grup şirketlerimizle, iki nokta arasında TIR taşımacılığı hizmeti sunuyoruz. Türkiye, Gürcistan, Azerbaycan, Türkmenistan ve İran arasındaki sınır ötesi güzergahlarda deneyimli filo ve saha ekiplerimizle sevkiyatlarınızı yönetiyoruz.",
      "svc-road.desc.p2": "Poti/Batum, Alat, Türkmenbaşı ve Banderabbas limanlarından gelen yüklerin karayolu ile iç bölgelere veya komşu ülkelere aktarımını sağlıyor; door-to-door ve port-to-port organizasyonlarla tedarik zincirinizin karayolu ayağını uçtan uca üstleniyoruz.",
      "svc-road.desc.cta": "Bu Hizmet İçin Teklif Al",
      "svc-road.advantages.eyebrow": "Neden Bizimle",
