      "svc-multimodal.meta.title": "Multimodal Taşımacılık | CEN Logistics Group",
      "svc-multimodal.meta.description": "Deniz, demir ve karayolunu tek bir zincirde birleştiren uçtan uca multimodal taşımacılık çözümleri.",
      "svc-multimodal.hero.subtitle": "Deniz, demir ve karayolunu tek bir zincirde birleştirerek, iki nokta arasında uçtan uca ve kesintisiz taşımacılık sunuyoruz.",
      "svc-multimodal.about.imgAlt": "Multimodal taşımacılık ekipmanları",
      "svc-multimodal.about.eyebrow": "Açıklama",
      "svc-multimodal.about.title": "Tek Merkezden Yönetilen Uçtan Uca Zincir",
      "svc-multimodal.about.p1": "CME Intermodal\u0026Shipping, ELS Intermodal Logistics ve CEN Logistics Georgia\u0027nın bölgesel güçlerini birleştirerek; denizyolu, demiryolu ve karayolunu tek bir tedarik zinciri yapısı altında birleştiriyoruz. Yükünüz, Poti/Batum, Alat, Türkmenbaşı veya Banderabbas limanlarından çıkıp demiryolu veya karayolu ile hedefine ulaşana kadar tek bir sorumlu ekip tarafından yönetilir.",
      "svc-multimodal.about.p2": "Bu sayede yükleme, aktarma ve sınır geçiş noktalarındaki koordinasyon kayıplarını ortadan kaldırıyor; müşterilerimize tek fatura, tek takip noktası ve tek sorumluluk sunuyoruz.",
      "svc-multimodal.about.ctaText": "Bu Hizmet İçin Teklif Al",
      "svc-multimodal.advantages.eyebrow": "Neden Bizimle",
      "svc-multimodal.advantages.title": "Avantajlar",
