      "svc-multimodal.advantages.card1.desc": "Deniz, demir ve karayolu ayaklarını tek bir operasyon ekibi uçtan uca koordine eder.",
      "svc-multimodal.advantages.card2.title": "Geniş Coğrafi Kapsam",
      "svc-multimodal.advantages.card2.desc": "Türkiye, Kafkasya, Orta Asya, Rusya, İran, Çin ve Avrupa arasında entegre güzergah seçenekleri.",
      "svc-multimodal.advantages.card3.title": "Tek Takip Noktası",
      "svc-multimodal.advantages.card3.desc": "Farklı taşıma türleri arasında geçişte tek bir raporlama ve iletişim kanalı.",
