      "svc-port.meta.description": "Poti, Batum, Alat, Bakü, Türkmenbaşı, Banderabbas, Amirabad ve Anzali limanlarında gümrüklü/gümrüksüz saha operasyonları.",
      "svc-port.hero.subtitle": "Poti, Batum, Alat, Bakü, Türkmenbaşı, Banderabbas, Amirabad ve Anzali limanlarında gümrüklü ve gümrüksüz saha operasyonları.",
      "svc-port.about.imgAlt": "Liman vinç ve konteyner operasyonu",
      "svc-port.about.eyebrow": "Açıklama",
      "svc-port.about.title": "Bölgenin Kilit Limanlarında Saha Operasyonu",
      "svc-port.about.p1": "Poti/Batum üzerinden denizyolu ve karayolu ile gelen tüm yüklerin demiryolu ile Orta Asya ülkelerine veya ters yönde taşınması ve liman handling hizmetleri; Gürcistan içinde taşıma ve lojistik hizmetleri; Kutaisi ve Poti Serbest Bölgeleri\u0027nde katma değerli lojistik hizmetleri sunuyoruz.",
      "svc-port.about.p2": "Alat limanı üzerinden gelen yüklerin Orta Asya ülkelerine veya ters yönde taşınması, Bakü limanları handling hizmetleri (gümrüklü ve gümrüksüz sahada); Türkmenbaşı Limanı üzerinden Orta Asya bağlantıları; Banderabbas, Amirabad ve Anzali limanlarında tüm liman handling işlemlerini gerçekleştiriyoruz.",
      "svc-port.about.ctaText": "Bu Hizmet İçin Teklif Al",
