      "svc-handling.meta.title": "Tahmil Tahliye | CEN Logistics Group",
      "svc-handling.meta.description": "Konteyner, dökme ve proje kargo yükleri için vinç ve elleçleme ekipmanlarıyla tahmil tahliye, lashing ve sertifikasyon hizmetleri.",
      "svc-handling.hero.subtitle": "Türkiye genelinde liman içi ve liman dışı depolarda konteyner, dökme ve proje kargo yükleri için güvenli yükleme-boşaltma hizmetleri.",
      "svc-handling.about.eyebrow": "Açıklama",
      "svc-handling.about.title": "Ölçü ve Tonaja Uygun Güvenli Elleçleme",
      "svc-handling.about.p1": "Ülkemiz limanlarında müşterilerimize ait yüklerin hem liman içi hem de liman dışı depolarda konteyner, dökme ve proje kargo yük türlerine göre, yükün ölçülerine ve tonajlarına uygun vinç ve diğer elleçleme ekipmanları ile güvenli bir hizmet standardıyla tahmil tahliye hizmetleri veriyoruz.",
      "svc-handling.about.p2": "Tahmil tahliye hizmetlerimizde yüklerin malzeme ve ekipmanların cins ve özelliklerine göre ayrılma işlemlerini, nakliye aşamasında hasar görmeyecek şekilde lashing hizmeti ile yükün güvenli olarak taşıma işlemlerini gerçekleştiriyoruz.",
      "svc-handling.chips.item1": "Door to Door",
      "svc-handling.chips.item2": "Port to Port",
