      "process.meta.title": "Taşıma Süreci | CEN Logistics Group",
      "process.meta.description": "Talep, planlama, operasyon, takip ve teslimat aşamalarından oluşan disiplinli taşıma sürecimizi keşfedin.",
      "process.hero.title": "Taşıma Sürecimiz",
      "process.hero.desc": "Talepten teslimata kadar her sevkiyatta uyguladığımız disiplinli, şeffaf ve izlenebilir 5 adımlı süreç.",
      "process.step1.title": "Talep",
      "process.step1.desc": "Yük türü, güzergah, ağırlık ve taşıma türü bilgilerinizi alıyoruz.",
      "process.step2.title": "Planlama",
      "process.step2.desc": "En uygun rota, taşıma türü ve operatör kombinasyonunu belirleriz.",
      "process.step3.title": "Operasyon",
      "process.step3.desc": "Sevkiyatı bölgesel saha ekiplerimiz ve operatör ortaklarımızla yürütürüz.",
      "process.step4.title": "Takip",
      "process.step4.desc": "Sevkiyatınızı düzenli raporlarla ve tek bir iletişim noktasından izleriz.",
      "process.step5.title": "Teslimat",
      "process.step5.desc": "Yükünüzü güvenle, zamanında ve eksiksiz olarak hedefine ulaştırırız.",
      "process.detail.eyebrow": "Detaylı Bakış",
      "process.detail.title": "Her Aşamada Ne Yapıyoruz?",
      "process.timeline1.year": "01 — Talep",
      "process.timeline1.title": "İhtiyaç Analizi",
      "process.timeline1.desc": "Yük tipi (konteyner, dökme, proje kargo), ağırlık, güzergah ve zaman kısıtlarınızı iş geliştirme ekibimizle birlikte netleştiriyoruz. Bu aşamada web sitemizdeki \u003ca href=\"teklif-al.html\" style=\"color:var(--teal-accent);font-weight:600;\"\u003eTeklif Al\u003c/a\u003e formu veya doğrudan iletişim kanallarımız kullanılabilir.",
      "process.timeline2.year": "02 — Planlama",
      "process.timeline2.title": "Rota ve Operatör Seçimi",
      "process.timeline2.desc": "Denizyolu, demiryolu, karayolu veya multimodal seçenekleri arasında en uygun kombinasyonu; süre, maliyet ve güzergah güvenliğini gözeterek belirliyoruz. BTK Hattı, Middle Corridor ve Hazar/Volga güzergahları bu aşamada değerlendirilir.",
      "process.timeline3.year": "03 — Operasyon",
      "process.timeline3.title": "Saha Uygulaması",
      "process.timeline3.desc": "Yükleme, liman handling, tahmil tahliye, lashing ve sertifikasyon süreçlerini bölgesel grup şirketlerimiz ve operatör ortaklarımızla sahada yürütüyoruz.",
      "process.timeline4.year": "04 — Takip",
      "process.timeline4.title": "Şeffaf Raporlama",
      "process.timeline4.desc": "Sınır geçişleri, liman aktarmaları ve konum bilgilerini düzenli raporlarla paylaşıyor; tüm süreç boyunca tek bir sorumlu ekiple iletişim sağlıyoruz.",
      "process.timeline5.year": "05 — Teslimat",
      "process.timeline5.title": "Güvenli Kapanış",
      "process.timeline5.desc": "Yük varış noktasında teslim edilir; ilgili belgeler (CMR, konşimento, sertifikalar) eksiksiz şekilde tarafınıza ulaştırılır.",
      "process.assurance.eyebrow": "Güvence Altında",
      "process.assurance.title": "Sürecin Her Adımında Yanınızdayız",
      "process.value1.title": "Şeffaflık",
      "process.value1.desc": "Sürecin her aşamasında açık iletişim ve düzenli raporlama.",
      "process.value2.title": "7/24 Destek",
      "process.value2.desc": "Operasyon hattımız sınır ötesi süreçlerde kesintisiz aktif.",
      "process.value3.title": "Deneyimli Ekipler",
      "process.value3.desc": "Her bölgede uzman lojistik mühendisliği ve saha ekipleri.",
      "process.cta.title": "Sürecimizi sizin sevkiyatınızla birlikte deneyimleyin.",
      "process.cta.services": "Hizmetlerimizi İnceleyin",
