      "faq.meta.title": "Sıkça Sorulan Sorular | CEN Logistics Group",
      "faq.meta.description": "Hizmetlerimiz, faaliyet bölgelerimiz, teklif süreci ve taşıma türlerimiz hakkında sıkça sorulan sorular.",
      "faq.hero.title": "Sıkça Sorulan Sorular",
      "faq.hero.desc": "Hizmetlerimiz, faaliyet bölgelerimiz ve taşıma süreçlerimiz hakkında en çok merak edilen sorular.",
      "faq.q1.question": "CEN Logistics Group hangi taşıma türlerinde hizmet veriyor?",
      "faq.q1.answer": "Denizyolu (bulk ve konteyner), demiryolu (konteyner ve vagon), karayolu (TIR/dorse), multimodal taşımacılık, liman handling ve tahmil tahliye hizmetleri sunuyoruz. Detaylar için \u003ca href=\"hizmetler.html\" style=\"color:var(--teal-accent);font-weight:600;\"\u003eHizmetlerimiz\u003c/a\u003e sayfasını inceleyebilirsiniz.",
      "faq.q2.question": "Hangi ülkelerde faaliyet gösteriyorsunuz?",
      "faq.q2.answer": "Türkiye, Avrupa, Gürcistan, Azerbaycan, Türkmenistan, Kazakistan, Özbekistan, Çin, İran ve Rusya olmak üzere 10\u0027dan fazla ülkede hizmet veriyoruz. Detaylı bilgi için \u003ca href=\"faaliyet-bolgeleri.html\" style=\"color:var(--teal-accent);font-weight:600;\"\u003eFaaliyet Bölgeleri\u003c/a\u003e sayfamızdaki interaktif haritayı inceleyebilirsiniz.",
      "faq.q3.question": "Nasıl teklif alabilirim?",
      "faq.q3.answer": "\u003ca href=\"teklif-al.html\" style=\"color:var(--teal-accent);font-weight:600;\"\u003eTeklif Al\u003c/a\u003e sayfamızdaki formu doldurarak; yük türü, ağırlık, güzergah ve taşıma türü bilgilerinizi paylaşabilir, ya da doğrudan telefon, WhatsApp veya e-posta ile bize ulaşabilirsiniz.",
      "faq.q4.question": "Teklif sonrası süreç ne kadar sürer?",
      "faq.q4.answer": "Talebinizi aldıktan sonra iş geliştirme ekibimiz genellikle 24 saat içinde dönüş yapar. Güzergah ve yük tipine göre kesin teslim süresi, planlama aşamasında sizinle birlikte netleştirilir.",
      "faq.q5.question": "Konteyner, dökme yük ve proje kargo için ayrı hizmet alıyor musunuz?",
      "faq.q5.answer": "Evet. Tahmil tahliye hizmetlerimizde yükün ölçü ve tonajına uygun vinç ve ekipmanlarla konteyner, dökme ve proje kargo yükleri için ayrı ayrı elleçleme standartları uyguluyoruz. Detaylar için \u003ca href=\"hizmet-tahmil-tahliye.html\" style=\"color:var(--teal-accent);font-weight:600;\"\u003eTahmil Tahliye\u003c/a\u003e sayfamızı inceleyebilirsiniz.",
      "faq.q6.question": "BTK Hattı ve Middle Corridor üzerinden hangi ülkelere taşıma yapıyorsunuz?",
      "faq.q6.answer": "BTK Hattı ile Türkiye, Gürcistan, Azerbaycan, Türkmenistan, Özbekistan ve Kazakistan arasında; Middle Corridor üzerinden ise Çin\u0027den Türkiye ve Avrupa\u0027ya düzenli demiryolu konteyner taşımaları gerçekleştiriyoruz.",
      "faq.q7.question": "Sevkiyatımı nasıl takip edebilirim?",
      "faq.q7.answer": "Operasyon ekibimiz sevkiyatınız boyunca düzenli raporlama sağlar; sınır geçişleri, liman aktarmaları ve konum güncellemeleri size tek bir iletişim noktasından iletilir.",
      "faq.q8.question": "Acil durumlarda 7/24 destek alabiliyor muyum?",
      "faq.q8.answer": "Evet. Operasyon hattımız, sınır ötesi süreçlerinizde kesintisiz destek vermek üzere 7/24 aktiftir. Telefon veya WhatsApp üzerinden bize her zaman ulaşabilirsiniz.",
      "faq.cta.title": "Aradığınız sorunun cevabını bulamadınız mı?",
      "faq.cta.contact": "Bize Ulaşın",
