      "blog-iran.meta.title": "CEN Logistics Group İran Koridorunda Operasyonlarını Genişletiyor | Blog",
      "blog-iran.meta.description": "Banderabbas, Amirabad ve Anzali limanlarındaki handling kapasitemizi artırarak Orta Asya bağlantılarımızı güçlendiriyoruz.",
      "blog-iran.meta.category": "Şirket Haberleri",
      "blog-iran.hero.title": "CEN Logistics Group İran Koridorunda Operasyonlarını Genişletiyor",
      "blog-iran.hero.subtitle": "Banderabbas, Amirabad ve Anzali limanlarındaki handling kapasitemizi artırarak Orta Asya bağlantılarımızı güçlendiriyoruz.",
      "blog-iran.meta.readTime": "4 dk okuma",
      "blog-iran.cover.imgAlt": "Aktau Marine liman terminali",
      "blog-iran.body.p1": "CEN Logistics Group olarak, Karadeniz/Hazar Denizi ve Azerbaycan-İran koridorundaki büyümemizi sürdürüyoruz. Banderabbas, Amirabad ve Anzali limanlarındaki liman handling kapasitemizi artırarak, dünyanın her tarafından denizyoluyla gelen yüklerin demiryolu, TIR veya multimodal taşıma şekliyle Orta Asya ülkelerine, Azerbaycan\u0027a, Gürcistan\u0027a ve Rusya\u0027ya aktarımını hızlandırıyoruz.",
      "blog-iran.body.h2-1": "Neden İran Koridoru?",
      "blog-iran.body.p2": "İran üzerinden geçen güzergahlar, Hazar Denizi\u0027ne ve Orta Asya\u0027ya doğrudan erişim imkânı sunarak, Türkiye ile bölge ülkeleri arasındaki tedarik zincirlerini kısaltıyor. Sarakhs sınır kapısı üzerinden Türkmenistan-İran-Türkiye koridorunda gerçekleştirdiğimiz taşımalar, müşterilerimize alternatif ve esnek bir güzergah seçeneği sunuyor.",
      "blog-iran.body.h2-2": "Genişleyen Hizmet Kapsamımız",
      "blog-iran.body.list1-item1": "Banderabbas, Amirabad ve Anzali limanlarında tüm liman handling işlemleri",
      "blog-iran.body.list1-item2": "Hazar içi gemi taşıma (Türkmenistan, Rusya, Aktau)",
      "blog-iran.body.list1-item3": "İran içinde taşıma ve lojistik hizmetleri",
      "blog-iran.body.list1-item4": "Sarakhs sınır kapısından veya İran içinden Türkiye\u0027ye taşıma hizmetleri",
      "blog-iran.body.h2-3": "Sonraki Adımlar",
      "blog-iran.body.p3": "Bölgedeki saha ekiplerimizi güçlendirerek, önümüzdeki dönemde İran koridorundaki kapasitemizi daha da artırmayı planlıyoruz. Bu bölgede taşıma ihtiyacı olan müşterilerimizi \u003ca href=\"teklif-al.html\" style=\"color:var(--teal-accent);font-weight:600;\"\u003eTeklif Al\u003c/a\u003e sayfamızdan bize ulaşmaya davet ediyoruz.",
      "blog-iran.related.eyebrow": "İlginizi Çekebilir",
      "blog-iran.related.title": "Diğer Yazılar",
