      "blog-container-guide.meta.title": "FCL ve LCL Nedir? Konteyner Taşımacılığı Rehberi | Blog",
      "blog-container-guide.meta.description": "Full ve parsiyel konteyner yüklemesi arasındaki farkları, hangi durumda hangisini seçmeniz gerektiğini anlatıyoruz.",
      "blog-container-guide.breadcrumb.category": "Taşımacılık Rehberleri",
      "blog-container-guide.hero.title": "FCL ve LCL Nedir? Konteyner Taşımacılığı Rehberi",
      "blog-container-guide.hero.subtitle": "Full ve parsiyel konteyner yüklemesi arasındaki farkları, hangi durumda hangisini seçmeniz gerektiğini anlatıyoruz.",
      "blog-container-guide.meta.date": "18 Haziran 2026",
      "blog-container-guide.meta.readTime": "4 dk okuma",
      "blog-container-guide.meta.category": "Taşımacılık Rehberleri",
      "blog-container-guide.cover.alt": "Konteyner gemisi denizyolu taşıması",
      "blog-container-guide.body.p1": "Konteyner taşımacılığında en sık karşılaşılan terimlerden ikisi FCL (Full Container Load) ve LCL (Less than Container Load)\u0027dur. Yükünüzün hacmine göre doğru seçimi yapmak, hem maliyeti hem de teslim süresini doğrudan etkiler.",
      "blog-container-guide.body.h2-1": "FCL (Full Konteyner Yüklemesi) Nedir?",
      "blog-container-guide.body.p2": "FCL, bir konteynerin tamamının tek bir müşteriye ait yükle doldurulmasıdır. Yükünüz konteynerin tamamını dolduracak kadar büyükse veya yükün karışmasını istemiyorsanız FCL tercih edilir. Konteyner, yükleme noktasında mühürlenir ve varış noktasına kadar açılmaz; bu da güvenlik ve hız açısından avantaj sağlar.",
      "blog-container-guide.body.h2-2": "LCL (Parsiyel Konteyner Yüklemesi) Nedir?",
      "blog-container-guide.body.p3": "LCL, birden fazla müşteriye ait yükün aynı konteyner içinde birlikte taşınmasıdır. Küçük hacimli yükler için maliyet avantajı sunar; ancak konsolidasyon ve dekonsolidasyon süreçleri nedeniyle FCL\u0027e kıyasla biraz daha uzun sürebilir.",
      "blog-container-guide.body.h2-3": "Hangi Durumda Hangisini Seçmelisiniz?",
      "blog-container-guide.body.list1-item1": "\u003cstrong\u003eFCL:\u003c/strong\u003e Yük hacmi bir konteyneri dolduracak kadar büyükse, hassas veya yüksek değerli ürünler taşınıyorsa",
      "blog-container-guide.body.list1-item2": "\u003cstrong\u003eLCL:\u003c/strong\u003e Yük hacmi küçükse ve maliyet önceliğiniz varsa",
      "blog-container-guide.body.h2-4": "CEN Logistics Group Farkı",
      "blog-container-guide.body.p4": "Tahmil tahliye hizmetlerimiz kapsamında hem FCL hem de LCL yüklemeleri, konteyner iç dolum ve iç boşaltım süreçleriyle birlikte yönetiyoruz. Lashing ve sertifikasyon hizmetlerimizle, hangi yükleme türünü seçerseniz seçin, yükünüzün güvenli bir şekilde taşınmasını garanti ediyoruz.",
      "blog-container-guide.related.eyebrow": "İlginizi Çekebilir",
      "blog-container-guide.related.heading": "Diğer Yazılar",
