      "blog-website-launch.body.p1": "CEN Logistics Group olarak, müşterilerimizin hizmetlerimizi, faaliyet bölgelerimizi ve teklif süreçlerimizi çok daha kolay keşfedebilmesi için web sitemizi tamamen yeniledik.",
      "blog-website-launch.body.h2-1": "Yeni Sitede Neler Var?",
      "blog-website-launch.body.list1-item1": "Denizyolu, demiryolu, karayolu, multimodal, liman handling ve tahmil tahliye hizmetlerimiz için ayrı detay sayfaları",
      "blog-website-launch.body.list1-item2": "Türkiye, Avrupa, Gürcistan, Azerbaycan, Türkmenistan, Kazakistan, Özbekistan, Çin, İran ve Rusya\u0027yı kapsayan interaktif faaliyet haritası",
      "blog-website-launch.body.list1-item3": "Hızlı ve kolay \u003ca href=\"teklif-al.html\" style=\"color:var(--teal-accent);font-weight:600;\"\u003eTeklif Al\u003c/a\u003e formu",
      "blog-website-launch.body.list1-item4": "Sektörel gelişmeleri ve şirket haberlerini takip edebileceğiniz blog bölümü",
      "blog-website-launch.body.list1-item5": "Sıkça sorulan sorular ve güncellenmiş iletişim bilgileri",
      "blog-website-launch.body.h2-2": "Amacımız",
      "blog-website-launch.body.p2": "Yeni sitemizle, müşterilerimize daha şeffaf, daha hızlı ve daha kolay erişilebilir bir dijital deneyim sunmayı hedefliyoruz. Geri bildirimleriniz bizim için değerli; görüş ve önerilerinizi \u003ca href=\"iletisim.html\" style=\"color:var(--teal-accent);font-weight:600;\"\u003eİletişim\u003c/a\u003e sayfamızdan bize iletebilirsiniz.",
