      "about.meta.title": "About Us | CEN Logistics Group",
      "about.meta.description": "The story, mission, vision and values of CEN Logistics Group, and our growing operational network since 2020.",
      "about.breadcrumb.current": "About Us",
      "about.hero.title": "Bringing Regional Expertise Together Under One Global Brand",
      "about.hero.subtitle": "Since 2020, we have been bringing together the strength of our group companies in Turkey, Georgia, Azerbaijan and Turkmenistan under a single roof.",
      "about.story.media1Alt": "Port crane operation",
      "about.story.media2Alt": "Loading equipment into a container",
      "about.story.media3Alt": "Pipe transport on a rail wagon",
      "about.story.badgeLabel": "Uninterrupted growth since founding",
      "about.story.eyebrow": "Our Company Story",
      "about.story.title": "Three Companies, One Powerful Brand",
      "about.story.p1": "\u003cstrong\u003eCEN LOGISTICS GROUP\u003c/strong\u003e is a group of companies founded in 2020. Through its member companies — CME Intermodal\u0026amp;Shipping, ELS Intermodal Logistics and CEN Logistics Georgia — it provides multimodal and point-to-point trucking, sea container and bulk shipping, rail container and wagon transport, and loading/unloading services across Turkey.",
      "about.story.p2": "We manage your orders from a single center with expert business development and logistics engineering teams, combined with the regional experience, expertise and professional management capabilities of each of our operating companies. We came together to unite the multimodal strengths of our experienced companies in Turkey, Georgia, Azerbaijan and Turkmenistan to become a strong, sustainable, competitive, global brand.",
      "about.story.co1Name": "CME Intermodal\u0026amp;Shipping",
      "about.story.co1Desc": "Sea \u0026amp; multimodal transport",
      "about.story.co2Name": "ELS Intermodal Logistics",
      "about.story.co2Desc": "Rail \u0026amp; intermodal solutions",
      "about.story.co3Name": "CEN Logistics Georgia",
      "about.story.co3Desc": "Regional port \u0026amp; land operations",
      "about.mission.eyebrow": "Our Roadmap",
      "about.mission.title": "Our Mission and Vision",
      "about.mission.missionTitle": "Our Mission",
      "about.mission.missionText": "Our core mission is to provide our customers with flawless, efficient service at competitive prices. We operate with transparency, ethical values and an unwavering commitment to quality while fulfilling our responsibilities toward our customers, society and the environment.",
      "about.mission.visionTitle": "Our Vision",
      "about.mission.visionText": "To become the most trusted and preferred logistics brand under a single supply chain structure with all our affiliates, serving the flow of goods in the ever-growing trade between Europe \u0026 Turkey and the Central Asian countries.",
      "about.values.eyebrow": "Our Principles",
      "about.values.title": "Our Values",
      "about.values.subtitle": "As CEN LOGISTICS GROUP, we are committed to the following values.",
      "about.values.card1Alt": "Innovation icon",
      "about.values.card1Title": "Innovation and Technology",
      "about.values.card1Text": "We develop solution-oriented approaches to lead in a constantly evolving industry, staying up to date with the latest technologies and innovations.",
      "about.values.card2Alt": "Reliability icon",
      "about.values.card2Title": "Reliability and Quality",
      "about.values.card2Text": "We aim to be a trusted partner in the logistics industry by serving our customers without compromising on reliability and quality.",
      "about.values.card3Title": "Customer Focus",
      "about.values.card3Text": "Behind our success lies a management approach centered on customer focus and efficiency.",
      "about.values.card4Title": "Sustainable Growth",
      "about.values.card4Text": "We aim to be among the leading companies driving change in the industry by leveraging our know-how, services and network.",
      "about.timeline.eyebrow": "Our Journey",
      "about.timeline.title": "Timeline",
      "about.timeline.subtitle": "Key milestones of our growing operational network from founding to today.",
      "about.timeline.item1Title": "Founding of CEN Logistics Group",
      "about.timeline.item1Text": "CME Intermodal\u0026amp;Shipping, ELS Intermodal Logistics and CEN Logistics Georgia came together and united under the group umbrella.",
      "about.timeline.item2Title": "Expansion of the Regional Network",
      "about.timeline.item2Text": "Our port handling and rail operations in Georgia, Azerbaijan and Turkmenistan were strengthened.",
      "about.timeline.item3Title": "Integration of the BTK Line and the Middle Corridor",
      "about.timeline.item3Text": "Caucasus–Central Asia connections via the BTK line became a regular service; China–Europe rail transport via the Middle Corridor was added to our operations.",
      "about.timeline.item4Title": "Launch of the Iran Corridor",
      "about.timeline.item4Text": "Port handling at Bandar Abbas, Amirabad and Anzali, along with the Sarakhs border connection, were added to our operations.",
      "about.timeline.item5Year": "Today",
      "about.timeline.item5Title": "Uninterrupted Service in More Than 10 Countries",
      "about.timeline.item5Text": "We continue to provide loading/unloading services across Turkey and multimodal transport services in more than 10 countries.",
      "about.approach.eyebrow": "How We Work",
      "about.approach.title": "Our Management Approach",
      "about.approach.subtitle": "We act with the same diligence and transparency in every operation.",
      "about.approach.card1Title": "Customer-Centric Management",
      "about.approach.card1Text": "We plan every operation end-to-end according to the customer\u0027s specific needs and manage it with a single dedicated team.",
      "about.approach.card2Title": "Transparent Process Management",
      "about.approach.card2Text": "We build trust through regular reporting and open communication at every stage of the shipping process.",
      "about.approach.card3Title": "Sustainable Partnerships",
      "about.approach.card3Text": "We build long-term business partnerships with regional operators, port authorities and railway operators.",
      "about.team.eyebrow": "Our Team",
