      "regions.hero.title": "Our Regions of Operation",
      "regions.hero.subtitle": "With our Turkey-based operational network, we provide service in more than 10 countries stretching from Europe to China and from the Caucasus to Iran. Click on a country to view the services, transport modes, ports and rail connections offered there.",
