      "svc-sea.desc.p1": "We carry out transport of bulk and container cargo between ports worldwide. We also provide vessel transport for bulk cargo along the Volga River.",
      "svc-sea.desc.p2": "We safely connect Central Asia and the Caucasus by sea, providing vessel transport for transit cargo between and through neighboring countries within the Caspian Sea.",
