      "svc-rail.meta.title": "Rail Freight | CEN Logistics Group",
      "svc-rail.meta.description": "Rail container and wagon transport between Turkey, the Caucasus, Central Asia, Russia, Iran, Europe and China via the BTK line and the Middle Corridor.",
      "svc-rail.hero.title": "Rail Freight",
      "svc-rail.hero.subtitle": "Reliable rail container and wagon transport between Turkey, the Caucasus, Central Asia, Russia, Iran, Europe and China via the BTK Line and the Middle Corridor.",
      "svc-rail.desc.media.alt": "Rail container transport",
      "svc-rail.desc.eyebrow": "Overview",
      "svc-rail.desc.heading": "Seamless Rail Network with Regional Expertise",
      "svc-rail.desc.p1": "We provide our rail services through our main operators, who are expert, experienced and trusted brands in their own regions, together with our own experienced specialists.",
      "svc-rail.desc.p2": "Via the \u003cstrong\u003eBTK Line\u003c/strong\u003e, we carry out 20 ft, 40 ft and 45 ft container transport between Turkey, Georgia, Azerbaijan, Turkmenistan, Uzbekistan and Kazakhstan, as well as container and wagon transport between Kazakhstan, Uzbekistan, Turkmenistan and Russia. We offer regular rail container transport from China to Turkey and Europe via the \u003cstrong\u003eMiddle Corridor\u003c/strong\u003e, and manage Europe/Turkey rail container \u0026amp; wagon transport as well as container and wagon transport on the Turkmenistan–Iran–Turkey corridor.",
      "svc-rail.desc.cta": "Get a Quote for This Service",
      "svc-rail.advantages.eyebrow": "Why Choose Us",
