      "svc-rail.advantages.card1.desc": "Regional operator experience in 20/40/45 ft container transport on the Baku–Tbilisi–Kars line.",
      "svc-rail.advantages.card2.title": "Regular Middle Corridor Services",
      "svc-rail.advantages.card2.desc": "Regular rail container shipments from China to Turkey and Europe via the Middle Corridor.",
      "svc-rail.advantages.card3.title": "Extensive Corridor Network",
      "svc-rail.advantages.card3.desc": "Container \u0026amp; wagon transport capability between Kazakhstan, Uzbekistan, Turkmenistan, Russia, Iran and Europe.",
