      "svc-road.desc.eyebrow": "Overview",
      "svc-road.desc.heading": "Flexible Point-to-Point Road Solutions",
      "svc-road.desc.p1": "Through the group companies under the CEN Logistics Group umbrella, we offer point-to-point TIR transport services. We manage your shipments with our experienced fleet and field teams on cross-border routes between Turkey, Georgia, Azerbaijan, Turkmenistan and Iran.",
      "svc-road.desc.p2": "We provide onward road transport of cargo arriving from the ports of Poti/Batumi, Alat, Turkmenbashi and Bandar Abbas to inland regions or neighboring countries, handling the road leg of your supply chain end-to-end with door-to-door and port-to-port organizations.",
