      "svc-multimodal.meta.title": "Multimodal Transport | CEN Logistics Group",
      "svc-multimodal.meta.description": "End-to-end multimodal transport solutions combining sea, rail and road in a single chain.",
      "svc-multimodal.hero.subtitle": "By combining sea, rail and road transport into a single chain, we provide seamless end-to-end transportation between two points.",
      "svc-multimodal.about.imgAlt": "Multimodal transport equipment",
      "svc-multimodal.about.eyebrow": "Overview",
      "svc-multimodal.about.title": "An End-to-End Chain Managed from a Single Center",
      "svc-multimodal.about.p1": "By combining the regional strengths of CME Intermodal \u0026 Shipping, ELS Intermodal Logistics and CEN Logistics Georgia, we bring sea, rail and road transport together under a single supply chain structure. From the moment your cargo leaves the ports of Poti/Batumi, Alat, Turkmenbashi or Bandar Abbas until it reaches its destination by rail or road, it is managed by a single accountable team.",
      "svc-multimodal.about.p2": "This eliminates coordination losses at loading, transfer and border-crossing points, allowing us to offer our customers a single invoice, a single point of tracking and a single point of accountability.",
      "svc-multimodal.about.ctaText": "Get a Quote for This Service",
      "svc-multimodal.advantages.eyebrow": "Why Choose Us",
      "svc-multimodal.advantages.title": "Advantages",
      "svc-multimodal.advantages.card1.title": "Single Accountable Team",
      "svc-multimodal.advantages.card1.desc": "A single operations team coordinates the sea, rail and road legs from end to end.",
      "svc-multimodal.advantages.card2.title": "Broad Geographic Coverage",
      "svc-multimodal.advantages.card2.desc": "Integrated route options between Turkey, the Caucasus, Central Asia, Russia, Iran, China and Europe.",
      "svc-multimodal.advantages.card3.title": "Single Tracking Point",
      "svc-multimodal.advantages.card3.desc": "A single reporting and communication channel across transitions between different transport modes.",
