      "svc-port.about.p2": "We carry out the transport of cargo arriving via the port of Alat to Central Asian countries and vice versa, handling services at the ports of Baku (in both customs and non-customs areas); Central Asia connections via the port of Turkmenbashi; and all port handling operations at the ports of Bandar Abbas, Amirabad and Anzali.",
