      "svc-handling.hero.subtitle": "Safe loading and unloading services for container, bulk and project cargo at port and off-port warehouses across Turkey.",
      "svc-handling.about.eyebrow": "Overview",
      "svc-handling.about.title": "Safe Handling Matched to Size and Tonnage",
      "svc-handling.about.p1": "At ports across our country, we provide loading and unloading services for our customers\u0027 container, bulk and project cargo, in both port and off-port warehouses, using cranes and other handling equipment matched to the cargo\u0027s size and tonnage, all to a safe service standard.",
      "svc-handling.about.p2": "In our loading and unloading services, we sort cargo according to the type and characteristics of the materials and equipment, and secure it with lashing services so that it is transported safely and undamaged.",
