      "process.meta.title": "Shipping Process | CEN Logistics Group",
      "process.meta.description": "Discover our disciplined shipping process, from request and planning through operations, tracking and delivery.",
      "process.hero.title": "Our Shipping Process",
      "process.hero.desc": "A disciplined, transparent and traceable 5-step process we apply to every shipment, from request to delivery.",
      "process.step1.title": "Request",
      "process.step1.desc": "We collect your cargo type, route, weight and transport mode details.",
      "process.step2.title": "Planning",
      "process.step2.desc": "We determine the most suitable route, transport mode and operator combination.",
      "process.step3.title": "Operation",
      "process.step3.desc": "We carry out the shipment with our regional field teams and operator partners.",
      "process.step4.title": "Tracking",
      "process.step4.desc": "We monitor your shipment with regular reports and a single point of contact.",
      "process.step5.title": "Delivery",
      "process.step5.desc": "We deliver your cargo safely, on time and in full to its destination.",
      "process.detail.eyebrow": "A Closer Look",
      "process.detail.title": "What We Do at Every Stage?",
      "process.timeline1.year": "01 — Request",
      "process.timeline1.title": "Needs Analysis",
      "process.timeline1.desc": "We clarify your cargo type (container, bulk, project cargo), weight, route and time constraints together with our business development team. At this stage, our \u003ca href=\"teklif-al.html\" style=\"color:var(--teal-accent);font-weight:600;\"\u003eGet a Quote\u003c/a\u003e form or our direct contact channels can be used.",
      "process.timeline2.year": "02 — Planning",
      "process.timeline2.title": "Route and Operator Selection",
      "process.timeline2.desc": "We determine the most suitable combination among sea, rail, road or multimodal options, taking duration, cost and route security into account. The BTK line, the Middle Corridor and Caspian/Volga routes are evaluated at this stage.",
      "process.timeline3.year": "03 — Operation",
      "process.timeline3.title": "Field Execution",
      "process.timeline3.desc": "We carry out loading, port handling, cargo handling, lashing and certification processes on-site with our regional group companies and operator partners.",
      "process.timeline4.year": "04 — Tracking",
      "process.timeline4.title": "Transparent Reporting",
      "process.timeline4.desc": "We share border crossings, port transshipments and location updates through regular reports, providing a single responsible team of contact throughout the process.",
      "process.timeline5.year": "05 — Delivery",
      "process.timeline5.title": "Secure Closeout",
      "process.timeline5.desc": "Your cargo is delivered at its destination; related documents (CMR, bill of lading, certificates) are provided to you in full.",
      "process.assurance.eyebrow": "Fully Covered",
      "process.assurance.title": "We Are with You at Every Step",
      "process.value1.title": "Transparency",
