      "faq.meta.title": "Frequently Asked Questions | CEN Logistics Group",
      "faq.meta.description": "Frequently asked questions about our services, regions of operation, quote process and transport modes.",
      "faq.hero.title": "Frequently Asked Questions",
      "faq.hero.desc": "The most common questions about our services, regions of operation and shipping processes.",
      "faq.q1.question": "Which transport modes does CEN Logistics Group provide?",
      "faq.q1.answer": "We offer sea freight (bulk and container), rail freight (container and wagon), road freight (trailer/semi-trailer), multimodal transport, port handling and loading \u0026 unloading services. See our \u003ca href=\"hizmetler.html\" style=\"color:var(--teal-accent);font-weight:600;\"\u003eServices\u003c/a\u003e page for details.",
      "faq.q2.question": "In which countries do you operate?",
      "faq.q2.answer": "We operate in more than 10 countries, including Turkey, Europe, Georgia, Azerbaijan, Turkmenistan, Kazakhstan, Uzbekistan, China, Iran and Russia. See the interactive map on our \u003ca href=\"faaliyet-bolgeleri.html\" style=\"color:var(--teal-accent);font-weight:600;\"\u003eRegions We Serve\u003c/a\u003e page for details.",
      "faq.q3.question": "How can I get a quote?",
      "faq.q3.answer": "You can fill out the form on our \u003ca href=\"teklif-al.html\" style=\"color:var(--teal-accent);font-weight:600;\"\u003eGet a Quote\u003c/a\u003e page, sharing your cargo type, weight, route and transport mode, or you can reach us directly by phone, WhatsApp or email.",
      "faq.q4.question": "How long does the process take after a quote?",
      "faq.q4.answer": "Once we receive your request, our business development team usually responds within 24 hours. The exact delivery time is finalized with you during the planning stage, depending on the route and cargo type.",
      "faq.q5.question": "Do you provide separate services for containers, bulk cargo and project cargo?",
      "faq.q5.answer": "Yes. In our loading \u0026 unloading services, we apply separate handling standards for container, bulk and project cargo loads using cranes and equipment suited to the size and tonnage of the cargo. See our \u003ca href=\"hizmet-tahmil-tahliye.html\" style=\"color:var(--teal-accent);font-weight:600;\"\u003eLoading \u0026 Unloading\u003c/a\u003e page for details.",
      "faq.q6.question": "Which countries do you serve via the BTK line and the Middle Corridor?",
      "faq.q6.answer": "Via the BTK line we operate between Turkey, Georgia, Azerbaijan, Turkmenistan, Uzbekistan and Kazakhstan; via the Middle Corridor we provide regular rail container shipments from China to Turkey and Europe.",
      "faq.q7.question": "How can I track my shipment?",
      "faq.q7.answer": "Our operations team provides regular reporting throughout your shipment; border crossings, port transshipments and location updates are communicated to you through a single point of contact.",
      "faq.q8.question": "Can I get 24/7 support in emergencies?",
      "faq.q8.answer": "Yes. Our operations line is active 24/7 to provide uninterrupted support for your cross-border processes. You can always reach us by phone or WhatsApp.",
      "faq.cta.title": "Couldn\u0027t find the answer to your question?",
      "faq.cta.contact": "Contact Us",
