      "blog-btk.cta.backToBlog": "Back to Blog",
      "blog-iran.meta.title": "CEN Logistics Group Expands Operations in the Iran Corridor | Blog",
      "blog-iran.meta.description": "We are strengthening our Central Asia connections by increasing our handling capacity at the ports of Bandar Abbas, Amirabad and Anzali.",
      "blog-iran.meta.category": "Company News",
      "blog-iran.hero.title": "CEN Logistics Group Expands Operations in the Iran Corridor",
      "blog-iran.hero.subtitle": "We are strengthening our Central Asia connections by increasing our handling capacity at the ports of Bandar Abbas, Amirabad and Anzali.",
      "blog-iran.meta.readTime": "4 min read",
      "blog-iran.cover.imgAlt": "Aktau Marine port terminal",
      "blog-iran.body.p1": "At CEN Logistics Group, we continue our growth in the Black Sea/Caspian Sea and Azerbaijan-Iran corridor. By increasing our port handling capacity at Bandar Abbas, Amirabad and Anzali, we are accelerating the transfer of cargo arriving by sea from all over the world onward to the Central Asian countries, Azerbaijan, Georgia and Russia by rail, truck or multimodal transport.",
      "blog-iran.body.h2-1": "Why the Iran Corridor?",
      "blog-iran.body.p2": "Routes passing through Iran shorten supply chains between Turkey and regional countries by providing direct access to the Caspian Sea and Central Asia. Our shipments via the Turkmenistan–Iran–Turkey corridor through the Sarakhs border crossing offer our customers an alternative and flexible route option.",
      "blog-iran.body.h2-2": "Our Expanding Service Scope",
      "blog-iran.body.list1-item1": "Full port handling operations at the ports of Bandar Abbas, Amirabad and Anzali",
      "blog-iran.body.list1-item2": "Intra-Caspian vessel transport (Turkmenistan, Russia, Aktau)",
      "blog-iran.body.list1-item3": "Transport and logistics services within Iran",
      "blog-iran.body.list1-item4": "Transport services to Turkey via the Sarakhs border crossing or from within Iran",
      "blog-iran.body.h2-3": "Next Steps",
      "blog-iran.body.p3": "By strengthening our field teams in the region, we plan to further increase our capacity in the Iran corridor in the coming period. We invite customers who need transport in this region to reach us via our \u003ca href=\"teklif-al.html\" style=\"color:var(--teal-accent);font-weight:600;\"\u003eGet a Quote\u003c/a\u003e page.",
      "blog-iran.related.eyebrow": "You Might Also Like",
      "blog-iran.related.title": "Other Articles",
      "blog-iran.related.readMore": "Read More",
      "blog-iran.related.viewMore": "View",
      "blog-iran.related.tagSektor": "Logistics Industry",
      "blog-iran.related.tagService": "Service",
      "blog-iran.related.tagDuyuru": "Announcements",
      "blog-iran.related.serviceDetail": "Service Details",
      "blog-iran.related.btk.title": "The BTK Line and the Middle Corridor: A New Route for Eurasian Trade",
      "blog-iran.related.btk.imgAlt": "Rail container transport",
      "blog-iran.related.limanHandling.title": "Our Port Handling Services",
      "blog-iran.related.limanHandling.imgAlt": "Port handling",
