      "blog-container-guide.related.readMore": "Read More",
      "blog-container-guide.related.card3.label": "Service Detail",
      "blog-container-guide.related.card3.title": "Our Sea Freight Services",
      "blog-container-guide.cta.heading": "Get a quote now for your FCL or LCL shipping needs.",
      "blog-container-guide.cta.backToBlog": "Back to Blog",
      "blog-website-launch.meta.title": "Our New Website Is Live | Blog",
      "blog-website-launch.meta.description": "We have renewed our website to make it easier for you to explore our services, regions of operation and quote process.",
      "blog-website-launch.breadcrumb.category": "Announcements",
      "blog-website-launch.hero.title": "Our New Website Is Live",
      "blog-website-launch.hero.subtitle": "We have renewed our website to make it easier for you to explore our services, regions of operation and quote process.",
      "blog-website-launch.meta.date": "June 5, 2026",
      "blog-website-launch.meta.readTime": "2 min read",
      "blog-website-launch.meta.category": "Announcements",
      "blog-website-launch.cover.alt": "Port crane and container operations",
      "blog-website-launch.body.p1": "At CEN Logistics Group, we have completely renewed our website so that our customers can discover our services, regions of operation and quote process much more easily.",
      "blog-website-launch.body.h2-1": "What\u0027s New on the Site?",
      "blog-website-launch.body.list1-item1": "Dedicated detail pages for our sea freight, rail freight, road freight, multimodal, port handling and loading \u0026 unloading services",
      "blog-website-launch.body.list1-item2": "An interactive regions-of-operation map covering Turkey, Europe, Georgia, Azerbaijan, Turkmenistan, Kazakhstan, Uzbekistan, China, Iran and Russia",
      "blog-website-launch.body.list1-item3": "A fast and easy \u003ca href=\"teklif-al.html\" style=\"color:var(--teal-accent);font-weight:600;\"\u003eGet a Quote\u003c/a\u003e form",
      "blog-website-launch.body.list1-item4": "A blog section where you can follow industry developments and company news",
      "blog-website-launch.body.list1-item5": "Frequently asked questions and updated contact information",
      "blog-website-launch.body.h2-2": "Our Goal",
      "blog-website-launch.body.p2": "With our new website, we aim to offer our customers a more transparent, faster and more easily accessible digital experience. Your feedback is valuable to us; you can share your thoughts and suggestions with us via our \u003ca href=\"iletisim.html\" style=\"color:var(--teal-accent);font-weight:600;\"\u003eContact\u003c/a\u003e page.",
      "blog-website-launch.related.eyebrow": "You May Also Like",
      "blog-website-launch.related.heading": "Other Articles",
      "blog-website-launch.related.tag.company": "Company News",
      "blog-website-launch.related.tag.page": "Page",
