      "index.meta.title": "CEN Logistics Group | Caucasus Europe Network",
      "index.meta.description": "CEN Logistics Group — Sea, rail and loading/unloading logistics solutions between Turkey, Georgia, Azerbaijan, Turkmenistan and Iran.",
      "index.hero.tag": "⚓ Serving Turkey • Georgia • Azerbaijan • Turkmenistan since 2020",
      "index.hero.title": "Your Trusted Partner in \u003cem\u003eMultimodal\u003c/em\u003e Transport Between Two Points",
      "index.hero.sub": "Combining the strengths of CME Intermodal\u0026amp;Shipping, ELS Intermodal Logistics and CEN Logistics Georgia, we manage road, rail and sea freight along with loading/unloading services from a single center.",
