      "index.about.badgeLbl": "Uninterrupted growth since our founding",
      "index.about.title": "Combining Regional Expertise Into a Global Brand",
      "index.about.p1": "\u003cstrong\u003eCEN LOGISTICS GROUP\u003c/strong\u003e is a group of companies founded in 2020. Through CME Intermodal\u0026amp;Shipping, ELS Intermodal Logistics and CEN Logistics Georgia, we provide multimodal and point-to-point trucking, sea container and bulk transport, rail container and wagon transport, and loading/unloading services across Turkey.",
      "index.about.p2": "We manage your orders from a single center with our expert business development and logistics engineering teams — combined with the regional experience, expertise and professional management capabilities of each operating company.",
      "index.about.co1": "Sea \u0026amp; multimodal transport",
      "index.about.co2": "Rail \u0026amp; intermodal solutions",
      "index.about.co3": "Regional port \u0026amp; land operations",
      "index.about.cta": "Our Full Story",
      "index.mission.eyebrow": "Our Roadmap",
      "index.mission.title": "Our Mission and Vision",
      "index.mission.h1": "Our Mission",
      "index.mission.p1": "Our core mission is to deliver flawless, efficient service to our customers at competitive prices. We operate with transparency, ethical values and a commitment to quality while fulfilling our responsibilities to our customers, society and the environment.",
      "index.mission.h2": "Our Vision",
      "index.mission.p2": "To become the most trusted and preferred transport brand under a single supply chain structure with all our affiliates, for the flow of goods in the ever-growing trade between Europe \u0026amp; Turkey and Central Asian countries.",
      "index.services.eyebrow": "What We Do",
      "index.services.sub": "We\u0027re with you at every step of your supply chain with our sea, rail, road, multimodal, port handling and loading/unloading services.",
      "index.services.card1.alt": "Container ship sea transport",
      "index.services.card1.desc": "Safe sea transport of bulk and container cargo from every port in the world.",
      "index.services.card2.alt": "Rail container transport",
      "index.services.card2.desc": "Transport between Turkey, the Caucasus, Central Asia and China via the BTK line and the Middle Corridor.",
      "index.services.card3.alt": "Road truck transport",
      "index.services.card3.desc": "Point-to-point, cross-border road transport with our truck and trailer fleet.",
      "index.services.card4.alt": "Multimodal transport equipment",
      "index.services.card4.desc": "End-to-end solutions combining sea, rail and road into a single chain.",
      "index.services.card5.alt": "Port crane and container operation",
      "index.services.card5.desc": "Bonded/non-bonded yard operations at the ports of Poti, Alat, Turkmenbashi and Iran.",
      "index.services.card6.alt": "Loading/unloading crane operation",
      "index.services.card6.desc": "Safe loading and unloading, lashing and certification services with cranes and equipment.",
      "index.why.eyebrow": "Why Us",
      "index.why.title": "Why You Should Choose Us",
      "index.why.sub": "We bring together our regional expertise, technological infrastructure and experienced team under a single assurance.",
      "index.why.card1.title": "Reliability",
      "index.why.card1.desc": "We are a reliable solutions partner with flawless operational standards and transparent business processes.",
      "index.why.card2.title": "Speed",
      "index.why.card2.desc": "With our regional expertise and strong network, we get your cargo to its destination via the fastest route.",
      "index.why.card3.title": "Competitive Pricing",
      "index.why.card3.desc": "We offer competitive costs through economies of scale and direct operator relationships.",
      "index.why.card4.title": "Experienced Team",
      "index.why.card4.desc": "We stand by you with our logistics engineering and business development teams with regional experience.",
      "index.why.card5.title": "Technology",
      "index.why.card5.desc": "Track your shipment end-to-end with our innovative tracking and operations management solutions.",
      "index.why.card6.title": "24/7 Support",
      "index.why.card6.desc": "Our operations line is active 24/7 to provide uninterrupted support for your cross-border processes.",
      "index.map.eyebrow": "Our Global Network",
      "index.map.title": "Regional Activity Map",
      "index.map.sub": "With our Turkey-centered operations network, we serve corridors stretching from Europe to China, from the Caucasus to Iran. Click a country to view details.",
      "index.map.svgAria": "CEN Logistics regional activity map",
