      "regions.meta.title": "Регионы деятельности | CEN Logistics Group",
      "regions.meta.description": "Услуги, виды перевозок, порты и железнодорожные соединения, которые мы предоставляем в Турции, Европе, Грузии, Азербайджане, Туркменистане, Казахстане, Узбекистане, Китае, Иране и России.",
      "regions.breadcrumb.current": "Регионы деятельности",
      "regions.hero.title": "Наши регионы деятельности",
