      "svc-sea.meta.title": "Морские перевозки | CEN Logistics Group",
      "svc-sea.meta.description": "Морская перевозка навалочных и контейнерных грузов из всех портов мира; операции на реке Волге и Каспийском море.",
      "svc-sea.hero.subtitle": "Глобальный охват — безопасная морская перевозка навалочных и контейнерных грузов из портов всего мира.",
      "svc-sea.desc.media.alt": "Морская перевозка контейнеров судном",
      "svc-sea.desc.eyebrow": "Описание",
      "svc-sea.desc.heading": "Надёжные морские перевозки от порта до порта",
      "svc-sea.desc.p1": "Мы осуществляем перевозку навалочных и контейнерных грузов между портами по всему миру. По реке Волге мы также предоставляем услуги судовой перевозки навалочных грузов.",
      "svc-sea.desc.p2": "Обеспечивая судовую перевозку транзитных грузов между соседними странами Каспийского моря и через них, мы надёжно поддерживаем морскую связь между Центральной Азией и Кавказом.",
      "svc-sea.desc.cta": "Запросить предложение по этой услуге",
