      "svc-rail.desc.media.alt": "Железнодорожная перевозка контейнеров",
      "svc-rail.desc.eyebrow": "Описание",
      "svc-rail.desc.heading": "Бесперебойная железнодорожная сеть с региональной экспертизой",
      "svc-rail.desc.p1": "Мы предоставляем железнодорожные услуги через наших основных операторов — опытных и надёжных брендов, являющихся экспертами в своих регионах, а также через собственных опытных специалистов.",
      "svc-rail.desc.p2": "По линии \u003cstrong\u003eБТК\u003c/strong\u003e мы осуществляем перевозку 20-, 40- и 45-футовых контейнеров между Турцией, Грузией, Азербайджаном, Туркменистаном, Узбекистаном и Казахстаном, а также контейнерные и вагонные перевозки между Казахстаном, Узбекистаном, Туркменистаном и Россией. Мы предлагаем регулярные железнодорожные контейнерные перевозки из Китая в Турцию и Европу по \u003cstrong\u003eСреднему коридору\u003c/strong\u003e, а также осуществляем железнодорожные контейнерные и вагонные перевозки Европа/Турция и перевозки по коридору Туркменистан–Иран–Турция.",
