      "svc-road.hero.title": "Автомобильные перевозки",
      "svc-road.hero.subtitle": "Гибкие и надёжные решения для перевозок между двумя точками, трансграничных и door-to-door автомобильных перевозок нашим парком тягачей и полуприцепов.",
