      "svc-road.desc.eyebrow": "Описание",
      "svc-road.desc.heading": "Гибкие автомобильные решения между двумя точками",
      "svc-road.desc.p1": "Через дочерние компании группы CEN Logistics Group мы предлагаем услуги автомобильной перевозки между двумя точками. Мы управляем вашими отправками с помощью опытного парка транспорта и полевых команд на трансграничных маршрутах между Турцией, Грузией, Азербайджаном, Туркменистаном и Ираном.",
      "svc-road.desc.p2": "Мы обеспечиваем автомобильную транспортировку грузов, прибывающих из портов Поти/Батуми, Алят, Туркменбаши и Бендер-Аббас, во внутренние регионы или соседние страны; благодаря организации door-to-door и port-to-port мы полностью берём на себя автомобильное звено вашей цепочки поставок.",
      "svc-road.desc.cta": "Запросить предложение по этой услуге",
      "svc-road.advantages.eyebrow": "Почему мы",
