      "svc-multimodal.hero.subtitle": "Объединяя морские, железнодорожные и автомобильные перевозки в единую цепочку, мы обеспечиваем бесперебойную перевозку груза от пункта отправления до пункта назначения.",
      "svc-multimodal.about.imgAlt": "Оборудование для мультимодальных перевозок",
      "svc-multimodal.about.eyebrow": "Описание",
      "svc-multimodal.about.title": "Комплексная цепочка перевозок под единым управлением",
      "svc-multimodal.about.p1": "Объединяя региональные возможности CME Intermodal \u0026 Shipping, ELS Intermodal Logistics и CEN Logistics Georgia, мы связываем морские, железнодорожные и автомобильные перевозки в единую цепочку поставок. С момента отправления груза из портов Поти/Батуми, Алят, Туркменбаши или Бендер-Аббас и до прибытия к месту назначения по железной дороге или автотранспортом, им управляет одна ответственная команда.",
      "svc-multimodal.about.p2": "Это устраняет потери координации в пунктах погрузки, перевалки и пересечения границы, позволяя нам предложить клиентам единый счёт, единую точку отслеживания и единую ответственность.",
      "svc-multimodal.about.ctaText": "Запросить предложение по этой услуге",
