      "svc-port.about.title": "Операции на ключевых портах региона",
      "svc-port.about.p1": "Мы оказываем услуги портового хендлинга и организуем железнодорожную перевозку всех грузов, прибывающих морем и автотранспортом через Поти/Батуми, в страны Центральной Азии и в обратном направлении; транспортные и логистические услуги внутри Грузии; а также логистические услуги с добавленной стоимостью в свободных зонах Кутаиси и Поти.",
      "svc-port.about.p2": "Мы осуществляем перевозку грузов, прибывающих через порт Алят, в страны Центральной Азии и в обратном направлении, услуги хендлинга в портах Баку (как в таможенной, так и во внетаможенной зоне); связи с Центральной Азией через порт Туркменбаши; а также все операции портового хендлинга в портах Бендер-Аббас, Амирабад и Энзели.",
