      "svc-handling.meta.description": "Услуги погрузки и разгрузки, крепления груза и сертификации для контейнерных, навалочных и проектных грузов с использованием кранов и погрузочного оборудования.",
      "svc-handling.hero.subtitle": "Безопасные услуги погрузки и разгрузки контейнерных, навалочных и проектных грузов на портовых и внепортовых складах по всей Турции.",
