      "svc-handling.about.title": "Безопасная обработка грузов с учётом габаритов и тоннажа",
      "svc-handling.about.p1": "В портах нашей страны мы оказываем услуги погрузки и разгрузки контейнерных, навалочных и проектных грузов наших клиентов — как на портовых, так и на внепортовых складах — с использованием кранов и другого погрузочного оборудования, подобранного в соответствии с габаритами и тоннажем груза, соблюдая высокий стандарт безопасности.",
      "svc-handling.about.p2": "В рамках наших услуг погрузки и разгрузки мы сортируем грузы по типу и характеристикам материалов и оборудования, а также обеспечиваем безопасную перевозку груза без повреждений с помощью услуг крепления (лашинга).",
