      "contact.cta.title": "Просто заполните форму для быстрого получения предложения.",
      "faq.meta.title": "Частые вопросы | CEN Logistics Group",
      "faq.meta.description": "Часто задаваемые вопросы о наших услугах, регионах деятельности, процессе получения предложения и видах перевозок.",
      "faq.hero.title": "Часто задаваемые вопросы",
      "faq.hero.desc": "Наиболее часто задаваемые вопросы о наших услугах, регионах деятельности и процессах перевозки.",
      "faq.q1.question": "Какие виды перевозок предоставляет CEN Logistics Group?",
      "faq.q1.answer": "Мы предлагаем морские перевозки (навалочные и контейнерные), железнодорожные перевозки (контейнерные и вагонные), автомобильные перевозки (тентованные/полуприцепы), мультимодальные перевозки, портовую обработку и погрузочно-разгрузочные работы. Подробности см. на странице \u003ca href=\"hizmetler.html\" style=\"color:var(--teal-accent);font-weight:600;\"\u003eУслуги\u003c/a\u003e.",
      "faq.q2.question": "В каких странах вы работаете?",
      "faq.q2.answer": "Мы работаем более чем в 10 странах, включая Турцию, Европу, Грузию, Азербайджан, Туркменистан, Казахстан, Узбекистан, Китай, Иран и Россию. Подробную информацию смотрите на интерактивной карте страницы \u003ca href=\"faaliyet-bolgeleri.html\" style=\"color:var(--teal-accent);font-weight:600;\"\u003eРегионы деятельности\u003c/a\u003e.",
      "faq.q3.question": "Как я могу получить предложение?",
      "faq.q3.answer": "Вы можете заполнить форму на странице \u003ca href=\"teklif-al.html\" style=\"color:var(--teal-accent);font-weight:600;\"\u003eПолучить предложение\u003c/a\u003e, указав тип груза, вес, маршрут и вид перевозки, либо связаться с нами напрямую по телефону, WhatsApp или эл. почте.",
      "faq.q4.question": "Сколько времени занимает процесс после получения предложения?",
      "faq.q4.answer": "После получения вашего запроса наш отдел развития бизнеса обычно отвечает в течение 24 часов. Точный срок доставки согласовывается с вами на этапе планирования в зависимости от маршрута и типа груза.",
      "faq.q5.question": "Предоставляете ли вы отдельные услуги для контейнеров, навалочных и проектных грузов?",
      "faq.q5.answer": "Да. В рамках погрузочно-разгрузочных работ мы применяем отдельные стандарты обработки для контейнерных, навалочных и проектных грузов, используя краны и оборудование, соответствующие размеру и тоннажу груза. Подробности см. на странице \u003ca href=\"hizmet-tahmil-tahliye.html\" style=\"color:var(--teal-accent);font-weight:600;\"\u003eПогрузочно-разгрузочные работы\u003c/a\u003e.",
      "faq.q6.question": "В какие страны вы осуществляете перевозки по линии BTK и Среднему коридору?",
      "faq.q6.answer": "По линии BTK мы работаем между Турцией, Грузией, Азербайджаном, Туркменистаном, Узбекистаном и Казахстаном; по Среднему коридору мы осуществляем регулярные железнодорожные контейнерные перевозки из Китая в Турцию и Европу.",
      "faq.q7.question": "Как я могу отследить свою отправку?",
      "faq.q7.answer": "Наша операционная команда обеспечивает регулярную отчётность на протяжении всей отправки; информация о пересечении границ, перевалках в портах и местоположении передаётся вам через единую точку контакта.",
      "faq.q8.question": "Могу ли я получить поддержку 24/7 в экстренных случаях?",
      "faq.q8.answer": "Да. Наша операционная линия работает круглосуточно и без выходных, обеспечивая бесперебойную поддержку для ваших трансграничных процессов. Вы всегда можете связаться с нами по телефону или WhatsApp.",
      "faq.cta.title": "Не нашли ответ на свой вопрос?",
      "faq.cta.contact": "Связаться с нами",
