      "blog-iran.meta.title": "CEN Logistics Group расширяет деятельность в Иранском коридоре | Блог",
      "blog-iran.meta.description": "Мы укрепляем наши связи со Средней Азией, увеличивая мощности обработки грузов в портах Бендер-Аббас, Амирабад и Анзали.",
      "blog-iran.meta.category": "Новости компании",
      "blog-iran.hero.title": "CEN Logistics Group расширяет деятельность в Иранском коридоре",
      "blog-iran.hero.subtitle": "Мы укрепляем наши связи со Средней Азией, увеличивая мощности обработки грузов в портах Бендер-Аббас, Амирабад и Анзали.",
      "blog-iran.meta.readTime": "4 мин чтения",
      "blog-iran.cover.imgAlt": "Портовый терминал Актау Марин",
      "blog-iran.body.p1": "В CEN Logistics Group мы продолжаем расти в коридоре Чёрное море/Каспийское море и Азербайджан-Иран. Увеличивая мощности обработки грузов в портах Бендер-Аббас, Амирабад и Анзали, мы ускоряем передачу грузов, прибывающих морем со всего мира, далее в страны Средней Азии, Азербайджан, Грузию и Россию железнодорожным, автомобильным или мультимодальным транспортом.",
      "blog-iran.body.h2-1": "Почему Иранский коридор?",
      "blog-iran.body.p2": "Маршруты через Иран сокращают цепочки поставок между Турцией и странами региона, обеспечивая прямой доступ к Каспийскому морю и Средней Азии. Наши перевозки по коридору Туркменистан–Иран–Турция через пограничный переход Серахс предлагают нашим клиентам альтернативный и гибкий вариант маршрута.",
      "blog-iran.body.h2-2": "Расширение спектра наших услуг",
      "blog-iran.body.list1-item1": "Полный комплекс портовых погрузо-разгрузочных работ в портах Бендер-Аббас, Амирабад и Анзали",
      "blog-iran.body.list1-item2": "Внутрикаспийские морские перевозки (Туркменистан, Россия, Актау)",
      "blog-iran.body.list1-item3": "Транспортные и логистические услуги внутри Ирана",
      "blog-iran.body.list1-item4": "Услуги перевозки в Турцию через пограничный переход Серахс или из внутренних районов Ирана",
      "blog-iran.body.h2-3": "Дальнейшие шаги",
      "blog-iran.body.p3": "Укрепляя наши полевые команды в регионе, мы планируем в ближайшее время ещё больше увеличить наши мощности в Иранском коридоре. Приглашаем клиентов, нуждающихся в перевозках в этом регионе, обращаться к нам через страницу \u003ca href=\"teklif-al.html\" style=\"color:var(--teal-accent);font-weight:600;\"\u003eПолучить предложение\u003c/a\u003e.",
      "blog-iran.related.eyebrow": "Вам может быть интересно",
      "blog-iran.related.title": "Другие статьи",
