      "blog-container-guide.meta.title": "Что такое FCL и LCL? Руководство по контейнерным перевозкам | Блог",
      "blog-container-guide.meta.description": "Рассказываем о различиях между полной и сборной контейнерной загрузкой и о том, какой вариант выбрать в зависимости от ситуации.",
      "blog-container-guide.breadcrumb.category": "Руководства по перевозкам",
      "blog-container-guide.hero.title": "Что такое FCL и LCL? Руководство по контейнерным перевозкам",
      "blog-container-guide.hero.subtitle": "Рассказываем о различиях между полной и сборной контейнерной загрузкой и о том, какой вариант выбрать в зависимости от ситуации.",
      "blog-container-guide.meta.date": "18 июня 2026",
      "blog-container-guide.meta.readTime": "4 мин чтения",
      "blog-container-guide.meta.category": "Руководства по перевозкам",
      "blog-container-guide.cover.alt": "Контейнеровоз, осуществляющий морскую перевозку",
      "blog-container-guide.body.p1": "Двумя наиболее часто встречающимися терминами в контейнерных перевозках являются FCL (Full Container Load — полная загрузка контейнера) и LCL (Less than Container Load — сборный груз). Правильный выбор в зависимости от объёма груза напрямую влияет как на стоимость, так и на сроки доставки.",
      "blog-container-guide.body.h2-1": "Что такое FCL (полная загрузка контейнера)?",
      "blog-container-guide.body.p2": "FCL означает, что весь контейнер заполняется грузом одного клиента. FCL предпочтителен, если ваш груз достаточно велик, чтобы заполнить весь контейнер, либо если вы не хотите смешивать свой груз с чужим. Контейнер пломбируется в пункте погрузки и не вскрывается до прибытия в пункт назначения, что обеспечивает преимущество как в безопасности, так и в скорости.",
      "blog-container-guide.body.h2-2": "Что такое LCL (сборная загрузка контейнера)?",
      "blog-container-guide.body.p3": "LCL означает совместную перевозку грузов нескольких клиентов в одном контейнере. Это даёт ценовое преимущество для небольших по объёму грузов, однако из-за процессов консолидации и деконсолидации срок доставки может быть несколько дольше, чем при FCL.",
      "blog-container-guide.body.h2-3": "В каком случае что выбрать?",
      "blog-container-guide.body.list1-item1": "\u003cstrong\u003eFCL:\u003c/strong\u003e если объём груза достаточен для заполнения контейнера, либо перевозятся хрупкие или высокоценные товары",
      "blog-container-guide.body.list1-item2": "\u003cstrong\u003eLCL:\u003c/strong\u003e если объём груза небольшой и приоритетом является стоимость",
      "blog-container-guide.body.h2-4": "Отличие CEN Logistics Group",
      "blog-container-guide.body.p4": "В рамках наших погрузочно-разгрузочных услуг мы управляем как FCL, так и LCL отправками вместе с процессами загрузки и выгрузки содержимого контейнера. Благодаря нашим услугам крепления груза (лашинг) и сертификации мы гарантируем безопасную перевозку вашего груза независимо от выбранного вами типа загрузки.",
      "blog-container-guide.related.eyebrow": "Вам также может быть интересно",
      "blog-container-guide.related.heading": "Другие статьи",
      "blog-container-guide.related.tag.service": "Услуга",
      "blog-container-guide.related.tag.industry": "Отрасль",
