      "blog-container-guide.related.card1.title": "Наши погрузочно-разгрузочные услуги",
      "blog-container-guide.related.card2.title": "Линия БТК и Средний коридор: новый торговый маршрут Евразии",
      "blog-container-guide.related.readMore": "Читать далее",
      "blog-container-guide.related.card3.label": "Детали услуги",
      "blog-container-guide.related.card3.title": "Наши услуги морских перевозок",
      "blog-container-guide.cta.heading": "Получите предложение прямо сейчас для вашей перевозки FCL или LCL.",
