      "index.meta.title": "CEN Logistics Group | Caucasus Europe Network",
      "index.meta.description": "CEN Logistics Group — Морские, железнодорожные и погрузочно-разгрузочные логистические решения между Турцией, Грузией, Азербайджаном, Туркменистаном и Ираном.",
      "index.hero.tag": "⚓ С 2020 года — Турция • Грузия • Азербайджан • Туркменистан",
