      "index.about.title": "Объединяем региональный опыт в глобальном бренде",
      "index.about.p1": "\u003cstrong\u003eCEN LOGISTICS GROUP\u003c/strong\u003e — группа компаний, основанная в 2020 году. Через входящие в неё компании CME Intermodal\u0026amp;Shipping, ELS Intermodal Logistics и CEN Logistics Georgia мы предоставляем услуги мультимодальных и прямых автомобильных перевозок, морских контейнерных и навалочных перевозок, железнодорожных контейнерных и вагонных перевозок, а также погрузочно-разгрузочные услуги по всей Турции.",
