      "index.mission.h2": "Наше видение",
      "index.mission.p2": "Стать самым надёжным и предпочитаемым перевозчиком в рамках единой цепочки поставок совместно со всеми нашими партнёрами — для потока товаров в постоянно растущей торговле между Европой, Турцией и странами Центральной Азии.",
