  function t(key, lang) {
    const dict = I18N[lang] || I18N.tr;
    if (Object.prototype.hasOwnProperty.call(dict, key)) return dict[key];
    if (Object.prototype.hasOwnProperty.call(I18N.tr, key)) return I18N.tr[key];
    return key;
  }

  const langChangeHooks = [];
  function onLangChange(fn) { langChangeHooks.push(fn); }

  let currentLang = "tr";
  try { currentLang = localStorage.getItem("cen_lang") || "tr"; } catch (e) {}

  function applyLanguage(lang) {
    if (!I18N[lang]) lang = "tr";
    currentLang = lang;
    document.documentElement.setAttribute("lang", lang);
    document.querySelectorAll("[data-i18n]").forEach((el) => {
      el.innerHTML = t(el.getAttribute("data-i18n"), lang);
    });
    document.querySelectorAll("[data-i18n-attr]").forEach((el) => {
      el.getAttribute("data-i18n-attr").split(",").forEach((pair) => {
        const idx = pair.indexOf(":");
        if (idx === -1) return;
        const attr = pair.slice(0, idx).trim();
        const key = pair.slice(idx + 1).trim();
        el.setAttribute(attr, t(key, lang));
      });
    });
    document.querySelectorAll(".lang-option").forEach((btn) => {
      btn.classList.toggle("active", btn.dataset.lang === lang);
    });
    document.querySelectorAll(".lang-switch-current").forEach((el) => {
      el.textContent = lang.toUpperCase();
    });
    try { localStorage.setItem("cen_lang", lang); } catch (e) {}
    langChangeHooks.forEach((fn) => fn(lang));
  }

  document.addEventListener("click", (e) => {
    const option = e.target.closest(".lang-option");
    if (option) {
      applyLanguage(option.dataset.lang);
      const menu = document.getElementById("langSwitchMenu");
      if (menu) menu.classList.remove("open");
      const btn = document.getElementById("langSwitchBtn");
      if (btn) btn.setAttribute("aria-expanded", "false");
      return;
    }
    if (!e.target.closest(".lang-switch")) {
      const menu = document.getElementById("langSwitchMenu");
      if (menu) menu.classList.remove("open");
    }
  });
  const langSwitchBtn = document.getElementById("langSwitchBtn");
  const langSwitchMenu = document.getElementById("langSwitchMenu");
  if (langSwitchBtn && langSwitchMenu) {
    langSwitchBtn.addEventListener("click", (e) => {
      e.stopPropagation();
      const open = langSwitchMenu.classList.toggle("open");
      langSwitchBtn.setAttribute("aria-expanded", String(open));
    });
  }

  /* ---------- Header scroll state ---------- */
  const header = document.getElementById("siteHeader");
  const backToTop = document.getElementById("backToTop");

  function onScroll() {
    const scrolled = window.scrollY > 40;
    header.classList.toggle("scrolled", scrolled);
    backToTop.classList.toggle("show", window.scrollY > 500);
    updateScrollSpy();
  }
  window.addEventListener("scroll", onScroll, { passive: true });
  onScroll();

  backToTop.addEventListener("click", () => {
    window.scrollTo({ top: 0, behavior: "smooth" });
  });

  /* ---------- Mobile menu ---------- */
  const navToggle = document.getElementById("navToggle");
  const mobileMenu = document.getElementById("mobileMenu");
  const menuBackdrop = document.getElementById("menuBackdrop");

  function closeMenu() {
    navToggle.classList.remove("open");
    mobileMenu.classList.remove("open");
    menuBackdrop.classList.remove("open");
    document.body.style.overflow = "";
  }
  function toggleMenu() {
    const isOpen = mobileMenu.classList.toggle("open");
    navToggle.classList.toggle("open", isOpen);
    menuBackdrop.classList.toggle("open", isOpen);
    document.body.style.overflow = isOpen ? "hidden" : "";
  }
  navToggle.addEventListener("click", toggleMenu);
  menuBackdrop.addEventListener("click", closeMenu);
  mobileMenu.querySelectorAll("a").forEach((a) => a.addEventListener("click", closeMenu));

  /* ---------- Active nav link (per page, multi-page site) ---------- */
  function updateScrollSpy() {
    /* no-op: kept as a named hook for onScroll(); active state is set once below by file name */
  }
  (function setActiveNavByFile() {
    const currentFile = (location.pathname.split("/").pop() || "index.html").split("?")[0] || "index.html";
    document.querySelectorAll(".nav-links a[href], .mobile-menu a[href]").forEach((a) => {
      const hrefRaw = a.getAttribute("href");
      if (!hrefRaw || hrefRaw.startsWith("#") || hrefRaw.startsWith("mailto:") || hrefRaw.startsWith("tel:")) return;
      const file = hrefRaw.split("#")[0].split("/").pop() || "index.html";
      if (file === currentFile) a.classList.add("active");
    });
  })();

  /* ---------- Reveal on scroll ---------- */
  const revealEls = document.querySelectorAll(".reveal");
  const io = new IntersectionObserver(
    (entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          entry.target.classList.add("in-view");
          io.unobserve(entry.target);
        }
      });
    },
    { threshold: 0.15, rootMargin: "0px 0px -60px 0px" }
  );
  revealEls.forEach((el) => io.observe(el));

  /* ---------- Service tabs ---------- */
  const tabs = document.querySelectorAll(".service-tab");
  const panels = document.querySelectorAll(".service-panel");
  tabs.forEach((tab) => {
    tab.addEventListener("click", () => {
      tabs.forEach((t) => t.classList.remove("active"));
      panels.forEach((p) => p.classList.remove("active"));
      tab.classList.add("active");
      const target = document.getElementById(tab.dataset.target);
      if (target) target.classList.add("active");
    });
  });

  /* ---------- Gallery lightbox ---------- */
  const galleryItems = Array.from(document.querySelectorAll(".gallery-item"));
  const lightbox = document.getElementById("lightbox");
  if (galleryItems.length && lightbox) {
    const lightboxImg = document.getElementById("lightboxImg");
    const lightboxCaption = document.getElementById("lightboxCaption");
    let currentIndex = 0;

    function openLightbox(index) {
      currentIndex = index;
      const item = galleryItems[currentIndex];
      const img = item.querySelector("img");
      lightboxImg.src = img.src;
      lightboxImg.alt = img.alt;
      const labelEl = item.querySelector(".g-label");
      lightboxCaption.textContent = (labelEl && labelEl.textContent) || item.dataset.caption || "";
      lightbox.classList.add("open");
      document.body.style.overflow = "hidden";
    }
    function closeLightbox() {
      lightbox.classList.remove("open");
      document.body.style.overflow = "";
    }
    function showRelative(delta) {
      currentIndex = (currentIndex + delta + galleryItems.length) % galleryItems.length;
      openLightbox(currentIndex);
    }

    galleryItems.forEach((item, index) => {
      item.addEventListener("click", () => openLightbox(index));
    });
    document.getElementById("lightboxClose").addEventListener("click", closeLightbox);
    document.getElementById("lightboxPrev").addEventListener("click", () => showRelative(-1));
    document.getElementById("lightboxNext").addEventListener("click", () => showRelative(1));
    lightbox.addEventListener("click", (e) => {
      if (e.target === lightbox) closeLightbox();
    });
    document.addEventListener("keydown", (e) => {
      if (!lightbox.classList.contains("open")) return;
      if (e.key === "Escape") closeLightbox();
      if (e.key === "ArrowLeft") showRelative(-1);
      if (e.key === "ArrowRight") showRelative(1);
    });
  }

  /* ---------- Footer year ---------- */
  const yearEl = document.getElementById("year");
  if (yearEl) yearEl.textContent = new Date().getFullYear();

  /* ---------- Page transition veil ---------- */
  const pageVeil = document.getElementById("pageVeil");
  if (pageVeil) {
    window.addEventListener("load", () => {
      setTimeout(() => pageVeil.classList.add("hidden"), 150);
    });
    document.querySelectorAll("a[href]").forEach((a) => {
      const href = a.getAttribute("href");
      if (!href || href === "" || href.startsWith("#") || href.startsWith("mailto:") ||
          href.startsWith("tel:") || href.startsWith("http") || href.startsWith("//") ||
          a.target === "_blank" || a.hasAttribute("download")) return;
      a.addEventListener("click", (e) => {
        if (e.metaKey || e.ctrlKey || e.shiftKey || e.altKey || e.button !== 0) return;
        e.preventDefault();
        pageVeil.classList.remove("hidden");
        setTimeout(() => { window.location.href = href; }, 380);
      });
    });
  }

  /* ---------- Animated counters ("Sayılarla Biz") ---------- */
  const counterEls = document.querySelectorAll(".counter-num");
  if (counterEls.length) {
    const counterIO = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (!entry.isIntersecting) return;
          const el = entry.target;
          const target = parseFloat(el.dataset.count || "0");
          const suffix = el.dataset.suffix || "";
          const hasDecimal = (el.dataset.count || "").includes(".");
          const duration = 1700;
          const startTime = performance.now();
          function tick(now) {
            const progress = Math.min((now - startTime) / duration, 1);
            const eased = 1 - Math.pow(1 - progress, 3);
            const value = target * eased;
            el.textContent = (hasDecimal ? value.toFixed(1) : Math.round(value).toLocaleString("tr-TR")) + suffix;
            if (progress < 1) requestAnimationFrame(tick);
          }
          requestAnimationFrame(tick);
          counterIO.unobserve(el);
        });
      },
      { threshold: 0.4 }
    );
    counterEls.forEach((el) => counterIO.observe(el));
  }

  /* ---------- Accordion (SSS) ---------- */
  document.querySelectorAll(".accordion-item").forEach((item) => {
    const trigger = item.querySelector(".accordion-trigger");
    if (!trigger) return;
    trigger.addEventListener("click", () => {
      const wasOpen = item.classList.contains("open");
      item.closest(".accordion").querySelectorAll(".accordion-item.open").forEach((openItem) => {
        if (openItem !== item) {
          openItem.classList.remove("open");
          openItem.querySelector(".accordion-trigger").setAttribute("aria-expanded", "false");
        }
      });
      item.classList.toggle("open", !wasOpen);
      trigger.setAttribute("aria-expanded", String(!wasOpen));
    });
  });

  /* ---------- Blog filter chips ---------- */
  const blogChips = document.querySelectorAll(".blog-filter-chips .chip-filter");
  const blogCards = document.querySelectorAll(".blog-card-grid .blog-card");
  if (blogChips.length && blogCards.length) {
    blogChips.forEach((chip) => {
      chip.addEventListener("click", () => {
        blogChips.forEach((c) => c.classList.remove("active"));
        chip.classList.add("active");
        const filter = chip.dataset.filter;
        blogCards.forEach((card) => {
          const show = filter === "all" || card.dataset.category === filter;
          card.style.display = show ? "" : "none";
        });
      });
    });
  }

  /* ---------- Quote / contact forms -> mailto ---------- */
  document.querySelectorAll("form[data-mailto]").forEach((form) => {
    form.addEventListener("submit", (e) => {
      e.preventDefault();
      const to = form.dataset.mailto;
      const subject = form.dataset.subject || "Web Sitesi Talebi";
      const data = new FormData(form);
      const lines = [];
      form.querySelectorAll("[name]").forEach((field) => {
        const label = field.closest(".form-group") ? field.closest(".form-group").querySelector("label") : null;
        const labelText = label ? label.textContent.replace("*", "").trim() : field.name;
        const value = data.get(field.name);
        if (value) lines.push(labelText + ": " + value);
      });
      const body = lines.join("\n");
      const mailtoUrl = "mailto:" + to + "?subject=" + encodeURIComponent(subject) + "&body=" + encodeURIComponent(body);
      window.location.href = mailtoUrl;
      const successEl = form.parentElement.querySelector(".form-success");
      if (successEl) successEl.classList.add("show");
    });
  });

